SINA_SMART["physics1-viscosity"] = {"lecture":"physics1-viscosity","title":"Viscosity applied to biological fluids","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physics1-viscosity:e0","text":"Viscosity = resistance to flow (internal friction).","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-viscosity:e1","text":"F = η·S·dv/dx; η in Pa·s (1 Pa·s = 10 poise).","topic":"Newton's law and units","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-viscosity:e2","text":"Water ≈ 10⁻³ Pa·s at 20 °C; η_r = η/η_water.","topic":"Newton's law and units","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-viscosity:e3","text":"Viscosity falls as temperature rises.","topic":"What changes viscosity","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-viscosity:e4","text":"Einstein: η = η°(1 + kφ); k = 2.6 spheres, > 1000 linear molecules.","topic":"What changes viscosity","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-viscosity:e5","text":"Blood: η = η_plasma(1 + 2.6 Ht); ↑ polycythaemia, ↓ anaemia, ↑ cold.","topic":"Blood viscosity; Newtonian fluids","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-viscosity:e6","text":"Plasma η ↑ in inflammation (fibrinogen, α2-globulin) and with dextrans.","topic":"Blood viscosity; Newtonian fluids","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-viscosity:e7","text":"Newtonian: η independent of velocity; blood is non-Newtonian.","topic":"Blood viscosity; Newtonian fluids","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"16sc04u":"a","14xdpv4":"a","k3edy7":"a","8hha1e":"a","ffzm40":"a","4jja2y":"a","oxzisr":"a","mrr6h8":"a","134tagq":"a","gts51n":"a","17z1c69":"a","juanud":"x"},"mapCounts":{"verified":0,"auto":11,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physics1-viscosity:e0":{"s":0,"u":["Viscosity = resistance to flow (internal friction).","An oily or honey-like fluid flows more slowly than water under the same pressure because of internal friction: viscosity , a fluid's resistance to flow , reflecting friction and intermolecular bonds that must be broken for layers to slide."],"dp":[]},"physics1-viscosity:e1":{"s":1,"u":["F = η·S·dv/dx; η in Pa·s (1 Pa·s = 10 poise).","Dimension M·L⁻¹·T⁻¹; SI unit pascal-second (Pa·s) (formerly poiseuille); cgs poise ( 1 Pa·s = 10 poise )."],"dp":[]},"physics1-viscosity:e2":{"s":1,"u":["Water ≈ 10⁻³ Pa·s at 20 °C; η_r = η/η_water.","Water ≈ 10⁻³ Pa·s at 20 °C; honey ≈ 10 Pa·s.","Relative viscosity η_r = η/η_water (unitless, easy to measure)."],"dp":[]},"physics1-viscosity:e3":{"s":2,"u":["Viscosity falls as temperature rises.","Pure fluids : depends on the fluid and temperature (viscosity falls as temperature rises )."],"dp":[]},"physics1-viscosity:e4":{"s":2,"u":["Einstein: η = η°(1 + kφ); k = 2.6 spheres, > 1000 linear molecules.","Einstein's law: η = η°(1 + k·φ) ; k rises with asymmetry: 2.6 for spheres , > 1000 for linear macromolecules ."],"dp":[]},"physics1-viscosity:e5":{"s":3,"u":["Blood: η = η_plasma(1 + 2.6 Ht); ↑ polycythaemia, ↓ anaemia, ↑ cold.","It rises with plasma viscosity or haematocrit ( polycythaemia ) and falls in anaemia ; it also rises with cold (poor circulation in extremities, chilblains).","Blood = red cells (≈ spheres, k = 2.6) suspended in plasma, with φ = haematocrit : η_blood = η_plasma(1 + 2.6·Ht) ."],"dp":[{"h":"Why cold fingers turn white","t":"Viscosity rises as temperature falls, so blood in cold fingers and toes flows less easily through narrow vessels, while cold also constricts those vessels. Slower flow reduces oxygen delivery, explaining pale, numb extremities and chilblains. Source: the lecture's blood viscosity slide."}]},"physics1-viscosity:e6":{"s":3,"u":["Plasma η ↑ in inflammation (fibrinogen, α2-globulin) and with dextrans.","Plasma viscosity rises in inflammation (more linear macromolecules: fibrinogen , α2-globulin) and with infusion of dextrans .","Blood = red cells (≈ spheres, k = 2.6) suspended in plasma, with φ = haematocrit : η_blood = η_plasma(1 + 2.6·Ht) ."],"dp":[]},"physics1-viscosity:e7":{"s":3,"u":["Newtonian: η independent of velocity; blood is non-Newtonian.","Newtonian fluids have a viscosity independent of flow velocity (water, plasma); non-Newtonian fluids change with velocity because their structure changes (blood: red cells aggregate at low flow and align at high flow)."],"dp":[]}},"meta":{"16sc04u":{"a":"recall","vg":"physics1-viscosity:e0/recall/1"},"14xdpv4":{"a":"recall","vg":"physics1-viscosity:e4/recall/1"},"k3edy7":{"a":"recall","vg":"physics1-viscosity:e1/recall/1"},"8hha1e":{"a":"recall","vg":"physics1-viscosity:e2/recall/1"},"ffzm40":{"a":"recall","vg":"physics1-viscosity:e3/recall/1"},"4jja2y":{"a":"recall","vg":"physics1-viscosity:e4/recall/1"},"oxzisr":{"a":"relationship","vg":"physics1-viscosity:e5/relationship/1"},"mrr6h8":{"a":"recall","vg":"physics1-viscosity:e5/recall/1"},"134tagq":{"a":"recall","vg":"physics1-viscosity:e6/recall/1"},"gts51n":{"a":"recall","vg":"physics1-viscosity:e7/recall/1"},"17z1c69":{"a":"recall","vg":"physics1-viscosity:e5/recall/2"}},"explRev":"d248687d8448"};
